/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

interface KoCountProps {
  /** The full-frame word that slams in after the count. */
  word?: string;
  /** Serif italic line under the word. */
  subline?: string;
  /** Small label next to the count, bottom left. */
  label?: string;
  /** Replaces the remocn mark. */
  logo?: React.ReactNode;
  /** Frames the count holds on ten before the word slams in. */
  hold?: number;
  /** Strength of the camera kick on each hit; 0 holds the frame still. */
  shake?: number;
  /** The count ticks. */
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the count, word and label. Load it yourself; Big Shoulders by default. */
  fontFamily?: string;
  /** Size of the foreground, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (internal clock = frame + 1, 30fps, speed 1):
//   0–56   the count: 1 → 10, a hard cut on every number, gaps tightening
//          8 → 4 frames. Every numeral is a different crop, scale and tilt and
//          lands with a small slam; the camera kick grows with the count. 8 is
//          an inverted frame, 10 fills with the "fluted" gradient
//  64–69   hard cut: the word slams in from 1.6× with echoes
//  69–71   impact: two frames of solid gradient ground with the word knocked
//          out, then a decaying shake
//  80–98   the serif subline wipes in, the logo rises; poster hold
const GAPS = [8, 8, 7, 7, 6, 6, 5, 5, 4];
const HOLD_TEN = 8;
const SLAM_LEN = 5;
const IMPACT_LEN = 2;
const SUB_DELAY = 11;
const LOGO_DELAY = 19;

const SLAM = Easing.bezier(0.12, 0.9, 0.25, 1);
const OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "fluted": bg #050507, [#1d2a8f, #2f7bff, #ff7a3d, #ffe2c4].
const FLUTED = ["#1D2A8F", "#2F7BFF", "#FF7A3D", "#FFE2C4"] as const;

const THEMES = {
  dark: {
    stage: "#08080A",
    ink: "#F3F2EF",
    dim: "#86858C",
    off: "#2A2A30",
    fill: (a: number) =>
      `linear-gradient(${a}deg, ${FLUTED[1]} 0%, #6A63E6 32%, ${FLUTED[2]} 68%, ${FLUTED[3]} 100%)`,
    ground: (a: number) =>
      `linear-gradient(${a}deg, ${FLUTED[0]} 0%, ${FLUTED[1]} 35%, ${FLUTED[2]} 75%, ${FLUTED[3]} 100%)`,
    impactInk: "#08080A",
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    dim: "#7E7D77",
    off: "#DAD8D1",
    fill: (a: number) =>
      `linear-gradient(${a}deg, ${FLUTED[0]} 0%, ${FLUTED[1]} 38%, #C8552B 72%, ${FLUTED[2]} 100%)`,
    ground: (a: number) =>
      `linear-gradient(${a}deg, ${FLUTED[0]} 0%, ${FLUTED[1]} 40%, ${FLUTED[2]} 80%, ${FLUTED[3]} 100%)`,
    impactInk: "#FFFFFF",
  },
} as const;

// Big Shoulders 500: cap/figure height 0.8em, cap top 0.0855em below a
// line-height-1 box. Figures advance ~0.35em, "1" a little less.
const CAP = 0.8;
const CAP_TOP = 0.0855;
const FIG = 0.36;

// Each count is its own shot: size (× height), centre, tilt.
const SHOTS = [
  { fs: 1.05, x: 0.5, y: 0.5, r: 0 },
  { fs: 1.45, x: 0.33, y: 0.58, r: 0 },
  { fs: 0.82, x: 0.7, y: 0.47, r: -3 },
  { fs: 1.9, x: 0.56, y: 0.36, r: 0 },
  { fs: 1.25, x: 0.3, y: 0.52, r: -5 },
  { fs: 2.2, x: 0.64, y: 0.64, r: 4 },
  { fs: 1.4, x: 0.48, y: 0.5, r: -7 },
  { fs: 2.6, x: 0.4, y: 0.46, r: 6 },
  { fs: 1.75, x: 0.6, y: 0.56, r: -9 },
  { fs: 1.22, x: 0.5, y: 0.52, r: -6 },
] as const;

const WORDS = [
  "one",
  "two",
  "three",
  "four",
  "five",
  "six",
  "seven",
  "eight",
  "nine",
  "ten",
];

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** Decaying camera shake that starts at `at`, stepped per frame. */
function shake(t: number, at: number, len: number, amp: number) {
  const d = Math.floor(t - at);
  if (d < 0 || d >= len) return { x: 0, y: 0 };
  const k = (1 - d / len) ** 2;
  return {
    x: amp * k * Math.sin(d * 2.4 + 0.6),
    y: amp * 0.6 * k * Math.cos(d * 3.1 + 0.3),
  };
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function KoCountBase({
  word = "Knockout",
  subline = "The old workflow did not get up.",
  label = "The count",
  logo,
  hold = HOLD_TEN,
  shake: shakeAmt = 1,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = shoulders,
  scale = 1,
  delay = 0,
  theme = "dark",
  speed = 1,
}: KoCountProps) {
  const glide = useGlide();
  const t = Math.max(0, useCurrentFrame() - delay) * speed + 1;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const stageFill =
    background === "transparent" ? "transparent" : (background ?? c.stage);
  const u = Math.min(W / 1280, H / 720);

  const countAt: number[] = [0];
  for (const g of GAPS) countAt.push(countAt[countAt.length - 1] + g);
  const koAt = countAt[9] + hold;
  const hitAt = koAt + SLAM_LEN;
  const subAt = hitAt + SUB_DELAY;
  const logoAt = hitAt + LOGO_DELAY;

  const idxAt = (tt: number) => {
    let i0 = 0;
    for (let i = 0; i < 10; i++) if (tt >= countAt[i]) i0 = i;
    return i0;
  };
  const idx = idxAt(t);
  const counting = t < koAt;
  const local = t - countAt[idx];

  // ── Camera: a kick on every count, growing; a big one on the word ─────────
  const camAt = (tt: number) => {
    const i = idxAt(tt);
    const sk =
      tt < koAt
        ? shake(tt, countAt[i] + 2, 5, (3 + i * 1.4) * u)
        : { x: 0, y: 0 };
    const sh = shake(tt, hitAt, 14, 22 * u);
    return { x: (sk.x + sh.x) * shakeAmt, y: (sk.y + sh.y) * shakeAmt };
  };
  const cam = camAt(t);
  const camX = cam.x;
  const camY = cam.y;
  const camStep = (a: number, b: number) => {
    const p = camAt(a);
    const q = camAt(b);
    return Math.abs(p.x - q.x) + Math.abs(p.y - q.y);
  };
  const camMoving =
    camStep(t + speed, t) > 1e-3 || camStep(t, Math.max(1, t - speed)) > 1e-3;

  const shot = SHOTS[idx];
  const numFs = shot.fs * H;
  const numSlam = SLAM(ramp(local, 0, 3));
  const numScale = (1.16 - 0.16 * numSlam) * (1 + 0.035 * ramp(local, 3, 10));
  const inverted = counting && idx === 7;
  const stage = inverted ? fg : stageFill;
  const numInk = inverted ? c.stage : fg;
  const isTen = idx === 9;
  const digits = String(idx + 1);
  const angle = 100 + 14 * Math.sin(t / 30);

  // ── The word ──────────────────────────────────────────────────────────────
  const letters = word.length;
  const wordFs = Math.min((0.9 * W) / (letters * 0.45), 0.56 * H);
  const wordCapH = CAP * wordFs;
  const wordCy = 0.44 * H;
  const wordScale = (d: number) =>
    (1.6 - 0.6 * SLAM(ramp(d, koAt, SLAM_LEN))) *
    (1 + 0.025 * ramp(d, hitAt, 60));
  const impact = t >= hitAt && t < hitAt + IMPACT_LEN * speed;
  const subP = OUT(ramp(t, subAt, 12));
  const logoP = OUT(ramp(t, logoAt, 10));

  const hud = (ink: string, dim: string) => (
    <>
      <div
        style={{
          position: "absolute",
          left: 48 * u,
          bottom: 40 * u,
          display: "flex",
          alignItems: "baseline",
          gap: 16 * u,
        }}
      >
        <div
          style={{
            fontFamily,
            fontWeight: 500,
            fontSize: 22 * u,
            letterSpacing: "0.26em",
            textTransform: "uppercase",
            color: dim,
          }}
        >
          {label}
        </div>
        <div
          style={{
            fontFamily: serif,
            fontStyle: "italic",
            fontWeight: 400,
            fontSize: 40 * u,
            letterSpacing: "-0.01em",
            color: ink,
          }}
        >
          {WORDS[idx]}
        </div>
      </div>
      <div
        style={{
          position: "absolute",
          right: 48 * u,
          bottom: 48 * u,
          display: "flex",
          gap: 7 * u,
        }}
      >
        {WORDS.map((w, i) => (
          <div
            key={w}
            style={{
              width: 14 * u,
              height: 30 * u,
              transform: "skewX(-18deg)",
              background:
                i < idx
                  ? dim
                  : i === idx
                    ? isTen
                      ? c.fill(100)
                      : accent
                    : c.off,
              opacity: i < idx && inverted ? 0.6 : 1,
            }}
          />
        ))}
      </div>
    </>
  );

  return (
    <AbsoluteFill style={{ background: stageFill, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: counting ? stage : impact ? c.ground(angle) : stageFill,
        }}
      />
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translate(${camX}px, ${camY}px)${glide(camMoving)}`,
          }}
        >
          {counting ? (
            <>
              {/* The numeral, cropped by the frame. */}
              <div
                style={{
                  position: "absolute",
                  left: shot.x * W - W,
                  width: 2 * W,
                  top: shot.y * H - CAP_TOP * numFs - (CAP * numFs) / 2,
                  display: "flex",
                  justifyContent: "center",
                  transform: `rotate(${shot.r}deg) scale(${numScale})`,
                  transformOrigin: `50% ${CAP_TOP * numFs + (CAP * numFs) / 2}px`,
                }}
              >
                <div
                  style={{
                    fontFamily,
                    fontWeight: 500,
                    fontSize: numFs,
                    lineHeight: 1,
                    letterSpacing: "-0.03em",
                    fontVariantNumeric: "tabular-nums",
                    whiteSpace: "nowrap",
                    color: isTen ? "transparent" : numInk,
                    backgroundImage: isTen ? c.fill(angle) : undefined,
                    WebkitBackgroundClip: isTen ? "text" : undefined,
                    backgroundClip: isTen ? "text" : undefined,
                    width: digits.length * FIG * numFs * 1.1,
                    textAlign: "center",
                  }}
                >
                  {digits}
                </div>
              </div>
              {hud(numInk, inverted ? c.off : c.dim)}
            </>
          ) : (
            <>
              {/* The word, with echoes trailing the slam. */}
              {[4, 2, 0].map((lag) => {
                const ghost = lag > 0;
                if (ghost && t >= hitAt) return null;
                const tt = t - lag;
                const op = ramp(tt, koAt, 2) * (ghost ? 0.22 / lag : 1);
                return (
                  <div
                    key={lag}
                    style={{
                      position: "absolute",
                      left: 0,
                      width: W,
                      top: wordCy - CAP_TOP * wordFs - wordCapH / 2,
                      display: "flex",
                      justifyContent: "center",
                      transform: `scale(${wordScale(tt)})${glide(
                        !camMoving &&
                          (midway(ramp(tt, koAt, SLAM_LEN)) ||
                            midway(ramp(tt, hitAt, 60))),
                      )}`,
                      transformOrigin: `50% ${CAP_TOP * wordFs + wordCapH / 2}px`,
                      opacity: op,
                    }}
                  >
                    <div
                      style={{
                        fontFamily,
                        fontWeight: 500,
                        fontSize: wordFs,
                        lineHeight: 1,
                        letterSpacing: "-0.01em",
                        textTransform: "uppercase",
                        whiteSpace: "nowrap",
                        color: impact || ghost ? c.impactInk : "transparent",
                        backgroundImage:
                          impact || ghost ? undefined : c.fill(angle),
                        WebkitBackgroundClip:
                          impact || ghost ? undefined : "text",
                        backgroundClip: impact || ghost ? undefined : "text",
                        ...(ghost ? { color: fg } : {}),
                        paddingRight: 0.02 * wordFs,
                      }}
                    >
                      {word}
                    </div>
                  </div>
                );
              })}

              {/* Subline wipes in from the left. */}
              {subP > 0 ? (
                <div
                  style={{
                    position: "absolute",
                    left: 0,
                    width: W,
                    top: wordCy + wordCapH / 2 + 34 * u,
                    display: "flex",
                    justifyContent: "center",
                    fontFamily: serif,
                    fontStyle: "italic",
                    fontWeight: 400,
                    fontSize: 50 * u,
                    lineHeight: 1.1,
                    letterSpacing: "-0.01em",
                    color: fg,
                    clipPath: `inset(-20% ${100 - 100 * subP}% -20% 0)`,
                    transform: `translateX(${(1 - subP) * -20 * u}px)`,
                  }}
                >
                  {subline}
                </div>
              ) : null}

              {logoP > 0 ? (
                <div
                  style={{
                    position: "absolute",
                    left: 0,
                    width: W,
                    bottom: 44 * u,
                    display: "flex",
                    justifyContent: "center",
                    opacity: logoP,
                    transform: `translateY(${(1 - logoP) * 14 * u}px)${glide(midway(logoP) && !camMoving)}`,
                  }}
                >
                  {logo ?? <RemocnLogo fontSize={34 * u} color={fg} />}
                </div>
              ) : null}
            </>
          )}
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  word: {
    type: "text-content",
    default: "Knockout",
    description: "Word",
  },
  subline: {
    type: "text-content",
    default: "The old workflow did not get up.",
    description: "Subline",
  },
  label: {
    type: "text-content",
    default: "The count",
    description: "Label",
  },
  hold: {
    type: "number",
    default: 8,
    min: 0,
    max: 30,
    step: 1,
    description: "Hold on ten (frames)",
    hiddenFromList: false,
  },
  shake: {
